export function ownerF213BaseMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0,objects=0,vertices=0;for(const c of components){const match=c.city==='leipzig'&&ownerF213Identity(c)&&!!c.displayEstimates?.F213Exterior;if(match)objects++;for(const b of c.batches){const count=b.positions.length/3;if(match){frames.set((b as Batch).frames,offset*5);for(let j=0;j<count;j++)paint.set([...b.color,2],4*(offset+j));vertices+=count;}offset+=count;}}return{objects,vertices,actualVisualAccepted:false};}
